def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))
                if prev.get('status') != 'won':
                    desperate_count += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif medium_supply:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    if urgency >= 7:
        bid = max(62.0, highest_prev + 2.0, avg_prev + 8.0)
    elif urgency >= 5:
        bid = max(48.0, avg_prev + 4.0)
    elif urgency >= 3:
        bid = max(32.0, avg_prev * 0.7)
    else:
        if highest_prev >= 120:
            bid = 14.0
        elif highest_prev >= 90:
            bid = 18.0
        elif highest_prev >= 60:
            bid = 24.0
        else:
            bid = 28.0 if medium_supply else 22.0

    if rich_count >= 2 and hp >= 6 and no_water_days == 0:
        bid = min(bid, 20.0)

    days_left = max(0, 10 - day)
    reserve_target = days_left * 18.0
    if budget > reserve_target + 80:
        bid += 6.0
    elif budget < reserve_target:
        bid = min(bid, 24.0 if urgency < 5 else bid)

    if day >= 8 and hp <= 4:
        bid = max(bid, 58.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

